import { ViewTransition } from 'react'

const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

/**
 * Slides page content horizontally based on the transition type carried by the
 * navigation: forward goes left, back goes right. Navigations without a type
 * (browser back/forward, router.refresh(), Suspense reveals) don't animate.
 *
 * This has to live inside each page.tsx — layouts persist across navigations,
 * so enter/exit would never fire there.
 */
export function PageTransition({ children }: { children: React.ReactNode }) {
  return (
    <ViewTransition enter={directional} exit={directional} default="none">
      {children}
    </ViewTransition>
  )
}

