/* ---------------------------------------------------------------- */
/* View transitions                                                 */
/* ---------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks made
   mid-animation get dropped. Let them through to the live page. */
::view-transition {
  pointer-events: none;
}

/* Shared element: the grid thumbnail morphs into the detail hero and back.
   The blur mid-flight hides interpolation artifacts while the 4/3 thumbnail
   reshapes into the 1/1 hero. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}
@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* Suspense reveal: the skeleton drops away, the real content rises in.
   Timing is deliberately asymmetric — the old content leaves quickly so it
   stops competing for attention, the new content arrives more gently. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}
@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* Directional navigation: forward moves content left, back moves it right.
   60px is enough to read as direction without making the eye chase it. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* ---------------------------------------------------------------- */
/* Reduced motion                                                   */
/* ---------------------------------------------------------------- */

/* Collapse every transition to an instant swap — the browser's behaviour
   without view transitions at all. The zeroed offsets are belt-and-braces:
   nothing travels across the viewport even if a UA still runs a frame. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  ::view-transition-old(*),
  ::view-transition-new(*) {
    --slide-offset: 0px;
  }

  /* The skeletons' infinite pulse is motion too — hold them at full opacity. */
  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

